<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Jobs\ProcessInvestigation; use App\Models\{DiagnosticReport,EvidenceFile,Investigation}; use App\Services\MuseAdapter; use Illuminate\Http\Request; use Illuminate\Support\Facades\Gate;
class InvestigationController extends Controller {
 public function index(Request $r){$ids=$r->user()->workspaces()->pluck('workspaces.id');return Investigation::whereIn('workspace_id',$ids)->latest()->get();}
 public function store(Request $r){$data=$r->validate(['name'=>'required|string|max:160','application_description'=>'nullable|string','framework'=>'nullable|string|max:80','environment'=>'nullable|string|max:80','problem'=>'nullable|string','workspace_id'=>'required|integer|exists:workspaces,id']);Gate::authorize('create',[Investigation::class,$data['workspace_id']]);$i=Investigation::create($data+['framework'=>$data['framework']??'Laravel / PHP','status'=>'draft']);$i->events()->create(['type'=>'created','message'=>'Investigation created']);return response()->json($i,201);}
 public function show(Request $r,Investigation $investigation){Gate::authorize('view',$investigation);return $investigation->load('evidence','findings','relationships','events');}
 public function destroy(Request $r,Investigation $investigation){Gate::authorize('delete',$investigation);$investigation->delete();return response()->noContent();}
 public function evidence(Request $r,Investigation $investigation){Gate::authorize('update',$investigation);$d=$r->validate(['category'=>'required|in:project,logs,hosting,browser','name'=>'required|string|max:255','content'=>'required|string|max:1048576']);$hash=hash('sha256',$d['content']);$e=EvidenceFile::firstOrCreate(['investigation_id'=>$investigation->id,'sha256'=>$hash],['category'=>$d['category'],'original_name'=>$d['name'],'mime_type'=>'text/plain','size'=>strlen($d['content']),'content'=>preg_replace('/(password|secret|token)\s*[=:]\s*\S+/i','$1=[REDACTED]',$d['content']),'state'=>'pending']);$investigation->events()->create(['type'=>'evidence','message'=>"Evidence added: {$e->original_name}"]);return response()->json($e,201);}
 public function evidenceIndex(Request $r,Investigation $investigation){Gate::authorize('view',$investigation);return $investigation->evidence()->latest()->get();}
 public function evidenceDestroy(Request $r,Investigation $investigation,EvidenceFile $evidence){Gate::authorize('update',$investigation);abort_unless($evidence->investigation_id===$investigation->id,404);$evidence->delete();return response()->noContent();}
 public function upload(Request $r,Investigation $investigation){Gate::authorize('update',$investigation);$r->validate(['category'=>'required|in:project,logs,hosting,browser','file'=>'required|file|max:10240']);$file=$r->file('file');$ext=strtolower($file->getClientOriginalExtension());$allowed=['txt','log','json','lock','php','js','ts','png','jpg','jpeg','webp','zip'];if(!in_array($ext,$allowed,true))abort(422,'Unsupported evidence type.');$raw=file_get_contents($file->getRealPath());$hash=hash('sha256',$raw);if($ext==='zip'){$text=$this->extractZip($file);$mime='application/zip';}else{$mime=$file->getMimeType();$text=in_array($ext,['png','jpg','jpeg','webp'],true)?'[Image evidence requires a verified visual-analysis provider.]':MuseAdapter::redact($raw);}$path=$file->storeAs('private/evidence/'.$investigation->id,$hash.'.'.$ext,'local');$e=EvidenceFile::firstOrCreate(['investigation_id'=>$investigation->id,'sha256'=>$hash],['category'=>$r->category,'original_name'=>$file->getClientOriginalName(),'storage_path'=>$path,'mime_type'=>$mime,'size'=>$file->getSize(),'content'=>$text,'state'=>'pending']);$investigation->events()->create(['type'=>'evidence','message'=>"File uploaded: {$e->original_name}"]);return response()->json($e,201);}
 private function extractZip(\Illuminate\Http\UploadedFile $file): string { $zip=new \ZipArchive(); if($zip->open($file->getRealPath())!==true)abort(422,'Unreadable archive.'); try{ if($zip->numFiles>50)abort(422,'Archive exceeds the 50-file limit.'); $total=0; $out=''; $readable=0; for($i=0;$i<$zip->numFiles;$i++){ $name=str_replace('\\','/',$zip->getNameIndex($i)); if($name===''||str_ends_with($name,'/'))continue; if(str_contains($name,'..')||preg_match('#^([a-zA-Z]:|/)#',$name))abort(422,'Archive contains an unsafe path.'); $entryExt=strtolower(pathinfo($name,PATHINFO_EXTENSION)); if(in_array($entryExt,['exe','bat','cmd','com','msi','ps1','sh','bin','dll','so','dylib'],true))abort(422,'Executable entries are not accepted.'); if(!in_array($entryExt,['txt','log','json','lock','php','js','ts','yml','yaml','xml','ini','env','dist','config','md'],true))continue; $stream=$zip->getStream($zip->getNameIndex($i)); if(!$stream)continue; $content=stream_get_contents($stream,1048576); fclose($stream); $total+=strlen($content); if($total>5242880)abort(422,'Archive exceeds the 5 MB extraction limit.'); $out.="--- {$name} ---\n".MuseAdapter::redact($content)."\n"; $readable++; } if($readable===0)abort(422,'No readable files in archive.'); return $out; } finally { $zip->close(); } }
 public function process(Request $r,Investigation $investigation){Gate::authorize('update',$investigation);$investigation->update(['status'=>'pending']);if(config('queue.default')==='sync'){ProcessInvestigation::dispatchSync($investigation->id);return $investigation->fresh()->load('findings');}ProcessInvestigation::dispatch($investigation->id);return response()->json(['status'=>'pending','message'=>'Diagnostics queued. Poll the investigation for findings.'],202);}
 public function report(Request $r,Investigation $investigation){Gate::authorize('view',$investigation);$investigation->load('evidence','findings');$data=$this->buildReport($investigation);DiagnosticReport::updateOrCreate(['investigation_id'=>$investigation->id],['content'=>$data]);$investigation->events()->create(['type'=>'report','message'=>'Report generated']);return response()->json($data);}
 public function reportExport(Request $r,Investigation $investigation){Gate::authorize('view',$investigation);$stored=DiagnosticReport::where('investigation_id',$investigation->id)->first();$data=$stored?->content??$this->buildReport($investigation->load('evidence','findings'));$name='deploysift-report-'.$investigation->id.'.json';return response()->json($data)->header('Content-Disposition',"attachment; filename=\"$name\"");}
 public function ai(Request $r,Investigation $investigation,MuseAdapter $muse){Gate::authorize('view',$investigation);$runs=$investigation->aiRuns()->latest()->take(10)->get();return response()->json($muse->status()+['runs'=>$runs]);}
 public function aiAnalyze(Request $r,Investigation $investigation,MuseAdapter $muse){Gate::authorize('update',$investigation);return response()->json($muse->analyze($investigation));}
 private function recommendationsFor(string $identifier): array {return match($identifier){
  'PHP_VERSION_MISMATCH'=>['Align the hosting PHP version with composer.json (PHP 8.3 or newer), or deliberately lower the requirement and re-test.','Run `composer check-platform-reqs` after the change to confirm the platform is satisfied.','Redeploy and confirm the HTTP 500 no longer occurs before closing the investigation.'],
  'DATABASE_CONNECTION_FAILURE'=>['Verify the database host, port, name, username, and password in the deployment environment configuration.','Confirm the database user is reachable and authorized from the application host.','Re-run migrations against a backup copy before touching production data.'],
  'VITE_ASSET_FAILURE'=>['Run `npm install` followed by `npm run build`, and confirm `public/build/manifest.json` is generated.','Ensure the deployment uploads the `public/build` directory to the host document root.','Hard-refresh the browser to rule out a stale cached bundle.'],
  'MISSING_APP_KEY'=>['Set a fresh key with `php artisan key:generate` in the deployment environment; never paste or commit the value.','Confirm the deployment reads the same environment file the app boots with.','Reproduce the failing request and confirm the key error is gone.'],
  'COMPOSER_PLATFORM_CONFLICT'=>['Run `composer check-platform-reqs` to list the exact blocked packages.','Align the required PHP version with the hosting runtime, or adjust the conflicting constraint deliberately.','Re-run `composer update` on a non-production copy first.'],
  'STORAGE_PERMISSION_FAILURE'=>['Ensure `storage/` and `bootstrap/cache/` are writable by the web-server user on the host.','Re-run the failing request without changing code. DeploySift never changes permissions itself.'],
  'DOCUMENT_ROOT_MISMATCH'=>['Point the hosting document root at the Laravel `public/` directory.','Verify with a request to a known route rather than trusting panel wording alone.'],
  'BROWSER_JS_EXCEPTION'=>['Open the linked evidence to read the full stack trace and failing line.','Fix the script error, rebuild assets if bundled, and re-run the browser flow.'],
  'HTTP_ASSET_FORBIDDEN'=>['Check file and directory permissions for the blocked asset path on the host.','Confirm hotlink or access rules are not denying the asset.'],
  'HTTP_ASSET_MISSING'=>['Rebuild with `npm run build` and confirm the asset exists in `public/build`.','Compare the manifest against the URLs the page requests.'],
  default=>['Confirm this observation against a second evidence source before changing anything.','Record the verification outcome on the investigation timeline.'],
 };}
 private function verificationChecklist(): array {return ['Open every evidence ID linked to a finding before acting on it.','Reproduce the failure once more after any fix, using the same evidence sources.','Matching-observation counts are not calibrated probabilities; treat them as qualitative support only.'];}
 private function supportingFor(Investigation $investigation,$f): array {$byId=$investigation->evidence->keyBy('id');$out=[];foreach((array)$f->evidence_ids as $id){if(isset($byId[$id]))$out[]='['.$byId[$id]->category.'] '.$byId[$id]->original_name;}return $out;}
 private function verificationStepsFor(string $identifier): array {return match($identifier){
  'PHP_VERSION_MISMATCH'=>['Run `php -v` on the host and compare with composer.json.','Re-run the failing request after the change.'],
  'DATABASE_CONNECTION_FAILURE'=>['Test the connection with the exact host, port, and credentials from the environment file.','Confirm the failing query succeeds after the fix.'],
  'VITE_ASSET_FAILURE'=>['Confirm `public/build/manifest.json` exists in the deployed files.','Reload the page and confirm the asset returns HTTP 200.'],
  'MISSING_APP_KEY'=>['Confirm the app boots without a key error.','Verify encrypted sessions and cookies work.'],
  'COMPOSER_PLATFORM_CONFLICT'=>['Re-run `composer validate` and `composer check-platform-reqs` cleanly.'],
  'STORAGE_PERMISSION_FAILURE'=>['Trigger the write that failed and confirm success.'],
  'DOCUMENT_ROOT_MISMATCH'=>['Request a route and a direct asset URL; both must resolve through public/.'],
  'BROWSER_JS_EXCEPTION'=>['Re-run the browser flow with the console open; no new exceptions.'],
  'HTTP_ASSET_FORBIDDEN'=>['Request the asset directly; expect HTTP 200.'],
  'HTTP_ASSET_MISSING'=>['Request the asset directly; expect HTTP 200 with manifest entry present.'],
  default=>['Confirm the observation against a second evidence source.'],
 };}
 private function buildReport(Investigation $investigation): array {return ['investigation'=>['id'=>$investigation->id,'name'=>$investigation->name,'framework'=>$investigation->framework,'environment'=>$investigation->environment,'problem'=>$investigation->problem,'synthetic'=>$investigation->is_synthetic],'generated_at'=>now()->toIso8601String(),'evidence_inventory'=>$investigation->evidence->map(fn($e)=>['id'=>$e->id,'category'=>$e->category,'name'=>$e->original_name,'facts'=>$e->extracted]),'findings'=>$investigation->findings->map(fn($f)=>['identifier'=>$f->identifier,'category'=>$f->category,'severity'=>$f->severity,'title'=>$f->title,'detail'=>$f->detail,'expected'=>$f->expected,'observed'=>$f->observed,'confidence_methodology'=>$f->confidence,'evidence_ids'=>$f->evidence_ids,'rule'=>$f->rule_name,'recommended_actions'=>$this->recommendationsFor($f->identifier),'supporting_observations'=>$this->supportingFor($investigation,$f),'contradicting_observations'=>['No contradicting evidence identified in the current evidence set.'],'verification_steps'=>$this->verificationStepsFor($f->identifier)]),'missing_information'=>['Only configuration visible in evidence is treated as confirmed.'],'verification_checklist'=>$this->verificationChecklist(),'ai'=>['status'=>'not_configured','note'=>'No AI claim is included without a verified provider adapter and evidence references.']];}
}
